import sys,json
raw=sys.stdin.read()
try:
    d=json.loads(raw)
except Exception as e:
    print("non-json:", raw[:1500]); sys.exit()
print("top keys:", list(d.keys()))
t=d.get("trail",d)
for k in ("id","number","title","state","status","head_sha","base","branch"):
    if k in t: print(k, "=", t[k])
for sec in ("runners","monitors","gates","findings","checks"):
    v=d.get(sec) or t.get(sec)
    if v is None: continue
    print("=== %s (%d)"%(sec, len(v) if hasattr(v,"__len__") else -1))
    items = v if isinstance(v,list) else list(v.items())
    for it in items[:30]:
        if isinstance(it,tuple): name,val=it
        else: name,val=it.get("name") or it.get("id") or it.get("key"), it
        if isinstance(val,dict):
            summary={k:val.get(k) for k in ("status","state","value","verdict","head_sha","sha","updated_at","run_id") if k in val}
            rat=val.get("rationale") or val.get("summary") or val.get("message") or ""
            print("-",name,summary); 
            if rat: print("   rationale:", str(rat)[:700].replace("\n"," | "))
        else: print("-",name,str(val)[:300])
'

